/** 
 * This method verifies if the provided argument contains at least one numeric character reference ( <code>CharRef	   ::=   	'&#' [0-9]+ ';' | '&#x' [0-9a-fA-F]+ ';</code>) for which the decimal or hexidecimal character value refers to an invalid XML 1.0 character.
 * @param string The input string
 * @return {@code true} if the input string contains an invalid numeric character reference, {@code false}otherwise.
 * @see http://www.w3.org/TR/2008/REC-xml-20081126/#dt-charref
 */
public static boolean hasIllegalCharacterReferences(String string){
  final Matcher matcher=XML_HAS_CHARREF.matcher(string);
  while (matcher.find()) {
    try {
      final String decValue=matcher.group(2);
      if (decValue != null) {
        final int value=Integer.parseInt(decValue);
        if (!isLegalXmlCharacter(value)) {
          return true;
        }
        continue;
      }
      final String hexValue=matcher.group(3);
      if (hexValue != null) {
        final int value=Integer.parseInt(hexValue,16);
        if (!isLegalXmlCharacter(value)) {
          return true;
        }
        continue;
      }
    } catch (NumberFormatException | IndexOutOfBoundsException e) {
      return false;
    }
    throw new IllegalStateException("An error occurred while searching for illegal character references in the value [" + string + "].");
  }
  return false;
}
